package employee.management.system;import com.toedter.calendar.JDateChooser;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.awt.event.ActionEvent;import java.awt.event.ActionListener;import java.util.Random;public class AddEmployee extends JFrame implements ActionListener {    Random ran = new Random();    int number = ran.nextInt(999999);    JTextField tname, tfather_name, taddress, tphone, taadhar, temail, tsalary, tdesignation;    JLabel tempID;    JDateChooser tdob;    JButton add, back;    JComboBox<String> Boxeducation;    public AddEmployee() {        setTitle("Add Employee Details");        setDefaultCloseOperation(EXIT_ON_CLOSE);        setSize(900, 700);        setLocationRelativeTo(null);        setLayout(null);        JPanel bgPanel = new JPanel() {            @Override            protected void paintComponent(Graphics g) {                super.paintComponent(g);                Graphics2D g2d = (Graphics2D) g;                GradientPaint gp = new GradientPaint(                        0, 0, new Color(25, 25, 25),                        getWidth(), getHeight(), new Color(60, 60, 60)                );                g2d.setPaint(gp);                g2d.fillRect(0, 0, getWidth(), getHeight());            }        };        bgPanel.setLayout(null);        setContentPane(bgPanel);        JLabel heading = new JLabel("Add Employee Details", SwingConstants.CENTER);        heading.setFont(new Font("Segoe UI", Font.BOLD, 30));        heading.setForeground(new Color(230, 230, 230));        heading.setBounds(250, 30, 400, 40);        bgPanel.add(heading);        Font labelFont = new Font("Segoe UI", Font.PLAIN, 17);        JLabel name = createLabel("Name", 70, 130, labelFont);        bgPanel.add(name);        tname = createTextField(200, 130);        bgPanel.add(tname);        JLabel father_name = createLabel("Father's Name", 460, 130, labelFont);        bgPanel.add(father_name);        tfather_name = createTextField(600, 130);        bgPanel.add(tfather_name);        JLabel dob = createLabel("Date of Birth", 70, 190, labelFont);        bgPanel.add(dob);        tdob = new JDateChooser();        tdob.setBounds(200, 190, 200, 30);        styleDateChooser(tdob);        bgPanel.add(tdob);        JLabel salary = createLabel("Salary", 460, 190, labelFont);        bgPanel.add(salary);        tsalary = createTextField(600, 190);        bgPanel.add(tsalary);        JLabel address = createLabel("Address", 70, 250, labelFont);        bgPanel.add(address);        taddress = createTextField(200, 250);        bgPanel.add(taddress);        JLabel phone = createLabel("Phone", 460, 250, labelFont);        bgPanel.add(phone);        tphone = createTextField(600, 250);        bgPanel.add(tphone);        JLabel email = createLabel("Email", 70, 310, labelFont);        bgPanel.add(email);        temail = createTextField(200, 310);        bgPanel.add(temail);        JLabel education = createLabel("Highest Education", 460, 310, labelFont);        bgPanel.add(education);        String items[] = {"BBA", "B.Tech", "BCA", "BA", "BSc", "B.Com", "MBA", "MCA", "MA", "M.Tech", "MSc", "PhD"};        Boxeducation = new JComboBox<>(items);        Boxeducation.setBounds(600, 310, 200, 30);        Boxeducation.setBackground(new Color(50, 50, 50));        Boxeducation.setForeground(Color.WHITE);        Boxeducation.setFont(new Font("Segoe UI", Font.PLAIN, 15));        bgPanel.add(Boxeducation);        JLabel designation = createLabel("Designation", 70, 370, labelFont);        bgPanel.add(designation);        tdesignation = createTextField(200, 370);        bgPanel.add(tdesignation);        JLabel aadhar = createLabel("Aadhar No.", 460, 370, labelFont);        bgPanel.add(aadhar);        taadhar = createTextField(600, 370);        bgPanel.add(taadhar);        JLabel empID = createLabel("Employee ID", 70, 430, labelFont);        bgPanel.add(empID);        tempID = new JLabel(String.valueOf(number));        tempID.setFont(new Font("Segoe UI", Font.BOLD, 18));        tempID.setForeground(new Color(111, 167, 218, 194));        tempID.setBounds(200, 430, 150, 30);        bgPanel.add(tempID);        add = createMetallicButton("ADD", new Color(70, 130, 180));        add.setBounds(500, 550, 150, 40);        add.addActionListener(this);        bgPanel.add(add);        back = createMetallicButton("BACK", new Color(100, 100, 100));        back.setBounds(300, 550, 150, 40);        back.addActionListener(this);        bgPanel.add(back);        setVisible(true);    }    private JLabel createLabel(String text, int x, int y, Font font) {        JLabel label = new JLabel(text);        label.setBounds(x, y, 160, 30);        label.setForeground(new Color(210, 210, 210));        label.setFont(font);        return label;    }    private JTextField createTextField(int x, int y) {        JTextField tf = new JTextField();        tf.setBounds(x, y, 200, 30);        tf.setBackground(new Color(45, 45, 45));        tf.setForeground(Color.WHITE);        tf.setCaretColor(Color.WHITE);        tf.setBorder(BorderFactory.createLineBorder(new Color(90, 90, 90)));        tf.setFont(new Font("Segoe UI", Font.PLAIN, 15));        return tf;    }    private JButton createMetallicButton(String text, Color baseColor) {        JButton button = new JButton(text);        button.setBackground(baseColor);        button.setForeground(Color.WHITE);        button.setFont(new Font("Segoe UI", Font.BOLD, 15));        button.setFocusPainted(false);        button.setBorder(new EmptyBorder(6, 15, 6, 15));        button.setUI(new MetallicButtonUI());        button.setCursor(new Cursor(Cursor.HAND_CURSOR));        return button;    }    private void styleDateChooser(JDateChooser chooser) {        JTextField editor = (JTextField) chooser.getDateEditor().getUiComponent();        editor.setBackground(new Color(45, 45, 45));        editor.setForeground(Color.WHITE);        editor.setCaretColor(Color.WHITE);        editor.setBorder(BorderFactory.createLineBorder(new Color(90, 90, 90)));        chooser.setFont(new Font("Segoe UI", Font.PLAIN, 15));    }    @Override    public void actionPerformed(ActionEvent e) {        if (e.getSource() == add) {            try {                String empID = tempID.getText();                String name = tname.getText();                String father_name = tfather_name.getText();                String dob = ((JTextField) tdob.getDateEditor().getUiComponent()).getText();                String salary = tsalary.getText();                String address = taddress.getText();                String phone = tphone.getText();                String email = temail.getText();                String education = (String) Boxeducation.getSelectedItem();                String designation = tdesignation.getText();                String aadhar = taadhar.getText();                conn c = new conn();                String query = "INSERT INTO employee (empId, name, father_name, dob, salary, address, phone, email, education, designation, aadhar) VALUES ('"                        + empID + "', '" + name + "', '" + father_name + "', '" + dob + "', '" + salary + "', '"                        + address + "', '" + phone + "', '" + email + "', '" + education + "', '" + designation + "', '" + aadhar + "')";                c.s.executeUpdate(query);                JOptionPane.showMessageDialog(null, " Employee details added successfully!");                setVisible(false);                new Main_class();            } catch (Exception ex) {                ex.printStackTrace();            }        } else {            setVisible(false);            new Main_class();        }    }    public static void main(String[] args) {        new AddEmployee();    }}